// HMAC (RFC 2104) built on the local pure-JS SHA-1.

import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64; // SHA-1 block size in bytes

export function hmacSha1(key, message) {
  let k = key instanceof Uint8Array ? key : Uint8Array.from(key);
  const m = message instanceof Uint8Array ? message : Uint8Array.from(message);

  // Keys longer than the block size are hashed first.
  if (k.length > BLOCK_SIZE) {
    k = sha1(k);
  }

  const ipad = new Uint8Array(BLOCK_SIZE + m.length);
  ipad.set(k, 0);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    ipad[i] ^= 0x36;
  }
  ipad.set(m, BLOCK_SIZE);

  const inner = sha1(ipad);

  const opad = new Uint8Array(BLOCK_SIZE + inner.length);
  opad.set(k, 0);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    opad[i] ^= 0x5c;
  }
  opad.set(inner, BLOCK_SIZE);

  return sha1(opad);
}

