// PBKDF2 key derivation (RFC 2898) with HMAC-SHA1 as the PRF,
// matching the Python `pbkdf2` package defaults:
//   PBKDF2(passphrase, salt) -> iterations=1000, digest=SHA-1.
// Strings are UTF-8 encoded, as the Python package does.

import { hmacSha1 } from './hmac.mjs';

export const DEFAULT_ITERATIONS = 1000;
export const PRF_OUTPUT_LENGTH = 20; // SHA-1 digest size

function toBytes(value) {
  if (typeof value === 'string') {
    return new TextEncoder().encode(value);
  }
  return value instanceof Uint8Array ? value : Uint8Array.from(value);
}

export function pbkdf2Sha1(passphrase, salt, dkLen, iterations = DEFAULT_ITERATIONS) {
  const password = toBytes(passphrase);
  const saltBytes = toBytes(salt);

  const blocks = Math.ceil(dkLen / PRF_OUTPUT_LENGTH);
  const derived = new Uint8Array(blocks * PRF_OUTPUT_LENGTH);

  // Salt plus 4-byte big-endian block index, as the PRF input for U1.
  const blockInput = new Uint8Array(saltBytes.length + 4);
  blockInput.set(saltBytes, 0);

  for (let block = 1; block <= blocks; block++) {
    blockInput[saltBytes.length] = (block >>> 24) & 0xff;
    blockInput[saltBytes.length + 1] = (block >>> 16) & 0xff;
    blockInput[saltBytes.length + 2] = (block >>> 8) & 0xff;
    blockInput[saltBytes.length + 3] = block & 0xff;

    let u = hmacSha1(password, blockInput);
    const t = Uint8Array.from(u);
    for (let i = 1; i < iterations; i++) {
      u = hmacSha1(password, u);
      for (let j = 0; j < PRF_OUTPUT_LENGTH; j++) {
        t[j] ^= u[j];
      }
    }
    derived.set(t, (block - 1) * PRF_OUTPUT_LENGTH);
  }

  return derived.slice(0, dkLen);
}

export function pbkdf2Sha1Hex(passphrase, salt, dkLen, iterations = DEFAULT_ITERATIONS) {
  const key = pbkdf2Sha1(passphrase, salt, dkLen, iterations);
  let hex = '';
  for (const byte of key) {
    hex += byte.toString(16).padStart(2, '0');
  }
  return hex;
}

