// Minimal manual command-line parser mirroring Python argparse behavior
// for this script: four required string options --a, --b, --c, --d.
// Supports both `--name value` and `--name=value` forms.
// On a usage error, argparse prints usage + error to stderr and exits 2.

const PROG = 'test6.mjs';
const OPTION_NAMES = ['a', 'b', 'c', 'd'];

function usageLine() {
  return `usage: ${PROG} [-h] --a A --b B --c C --d D`;
}

function fail(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const values = {};

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      process.stdout.write(usageLine() + '\n');
      process.exit(0);
    }

    if (!token.startsWith('--')) {
      fail(`unrecognized arguments: ${token}`);
    }

    let name;
    let value;
    const eq = token.indexOf('=');
    if (eq !== -1) {
      name = token.slice(2, eq);
      value = token.slice(eq + 1);
    } else {
      name = token.slice(2);
      if (i + 1 >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      value = argv[++i];
    }

    if (!OPTION_NAMES.includes(name)) {
      fail(`unrecognized arguments: ${token}`);
    }
    values[name] = value;
  }

  const missing = OPTION_NAMES.filter((name) => !(name in values));
  if (missing.length > 0) {
    fail(
      'the following arguments are required: ' +
        missing.map((name) => `--${name}`).join(', ')
    );
  }

  return values;
}

