import { pbkdf2Sha1Hex } from './lib/pbkdf2.mjs';

const args = parseArgs(process.argv.slice(2));

// First PBKDF2 derivation
const key1Hex = pbkdf2Sha1Hex(args.a, args.b, 16);
console.log(key1Hex);

